def simple_hash(text, mod=10):
    total = 0
    for ch in text:
        total = (total * 31 + ord(ch)) % mod
    return total

for word in ("apple", "banana", "cherry"):
    print(word, "->", simple_hash(word))

def two_sum(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        need = target - v
        if need in seen:
            return seen[need], i
        seen[v] = i
    return None

print(two_sum([2, 7, 11, 15], 9))

def char_counts(text):
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

counts = char_counts("mississippi")
print(counts)
print("出现最多:", max(counts, key=counts.get))

def group_anagrams(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups.setdefault(key, []).append(w)
    return list(groups.values())

print(group_anagrams(["eat", "tea", "tan", "ate", "nat", "bat"]))

def dedup_keep_order(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

print(dedup_keep_order([3, 1, 3, 2, 1, 5]))

def first_unique(text):
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in text:
        if counts[ch] == 1:
            return ch
    return None

print(first_unique("swiss"))

class OpenAddressTable:
    def __init__(self, capacity=8):
        self.slots = [None] * capacity

    def put(self, key, value):
        i = hash(key) % len(self.slots)
        while self.slots[i] is not None and self.slots[i][0] != key:
            i = (i + 1) % len(self.slots)
        self.slots[i] = (key, value)

    def get(self, key):
        i = hash(key) % len(self.slots)
        while self.slots[i] is not None:
            if self.slots[i][0] == key:
                return self.slots[i][1]
            i = (i + 1) % len(self.slots)
        return None

