def majority(nums):
    counts = {}
    for v in nums:
        counts[v] = counts.get(v, 0) + 1
        if counts[v] > len(nums) // 2:
            return v
    return None

print(majority([2, 2, 1, 2, 3, 2, 2]))

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return -1
        value = self.data.pop(key)
        self.data[key] = value
        return value

    def put(self, key, value):
        if key in self.data:
            self.data.pop(key)
        elif len(self.data) >= self.capacity:
            oldest = next(iter(self.data))
            self.data.pop(oldest)
        self.data[key] = value

cache = LRUCache(2)
cache.put("a", 1)
cache.put("b", 2)
cache.get("a")
cache.put("c", 3)
